// lesson03 ch04 解答
package main

import "fmt"

func main() {
	// 括弧がないと 80 + 90 + 70/3 となり、70/3 だけ先に計算されてしまいます。
	// 足し算を先にしたい意図を括弧で明示するのが読みやすいコードの基本です。
	// 240 / 3 は int 同士なので、結果もちょうど 80（int）になります。
	fmt.Println("平均点:", (80+90+70)/3)
}
